   120|export function sortMessagesByCanonicalOrder<T extends { id: string; createdAt?: string | null; serverCreatedAt?: string | null }>(messages: readonly T[]): T[] {
   121|  const resolveTimestamp = (message: T): number | null => {
   122|    const serverTime = Date.parse(message.serverCreatedAt ?? '');
   123|    if (Number.isFinite(serverTime)) return serverTime;
   124|
   125|    const createdTime = Date.parse(message.createdAt ?? '');
   126|    return Number.isFinite(createdTime) ? createdTime : null;
   127|  };
   128|
   129|  return [...messages].sort((left: T, right: T): number => {
   130|    const leftTime = resolveTimestamp(left);
   131|    const rightTime = resolveTimestamp(right);
   132|
   133|    if (leftTime !== null && rightTime !== null && leftTime !== rightTime) return leftTime - rightTime;
   134|    if (leftTime !== null && rightTime === null) return -1;
   135|    if (leftTime === null && rightTime !== null) return 1;
   136|    return left.id.localeCompare(right.id);
   137|  });
