     1|/**
     2| * Pure, runtime-free helpers for merging the IVX Owner AI conversation from its
     3| * two durable sources (remote Supabase rows + the local AsyncStorage shadow) and
     4| * for bounding the local shadow so it never grows without limit.
     5| *
     6| * This module deliberately has ZERO runtime imports (only a type-only import that
     7| * is erased at build time) so the conversation-state logic can be unit-tested
     8| * without React Native, Supabase, or AsyncStorage in scope. It is the single
     9| * source of truth for "which message wins" when the same turn exists both
    10| * locally and remotely — the logic that decides whether the chat survives a
    11| * reload, route change, logout/login, or a transient remote-read failure.
    12| */
    13|
    14|/** Minimal structural shape needed to merge/dedupe owner-chat messages. */
    15|export interface MergeableOwnerMessage {
    16|  id: string;
    17|  conversationId: string;
    18|  senderUserId: string | null;
    19|  senderRole: string;
    20|  body: string | null;
    21|  attachmentUrl: string | null;
    22|  attachmentName: string | null;
    23|  createdAt: string;
    24|}
    25|
    26|function normalizeMessageComparisonValue(value: string | null | undefined): string {
    27|  return value?.trim().toLowerCase() ?? '';
    28|}
    29|
    30|/** Exact-identity signature (conversation + sender + body + attachment + createdAt). */
    31|export function buildOwnerMessageSignature(message: MergeableOwnerMessage): string {
    32|  return [
    33|    normalizeMessageComparisonValue(message.conversationId),
    34|    normalizeMessageComparisonValue(message.senderUserId),
    35|    normalizeMessageComparisonValue(message.senderRole),
    36|    normalizeMessageComparisonValue(message.body),
    37|    normalizeMessageComparisonValue(message.attachmentUrl),
    38|    normalizeMessageComparisonValue(message.attachmentName),
    39|    normalizeMessageComparisonValue(message.createdAt),
    40|  ].join('::');
    41|}
    42|
    43|/**
    44| * Looser content key (conversation + role + body) used to recognise the SAME
    45| * logical turn after it has been re-persisted remotely with a fresh server id
    46| * and timestamp. Returns null for attachment-only messages (no body) so two
    47| * different uploads are never collapsed.
    48| */
    49|export function buildOwnerMessageContentKey(message: MergeableOwnerMessage): string | null {
    50|  const body = normalizeMessageComparisonValue(message.body);
    51|  if (body.length === 0) {
    52|    return null;
    53|  }
    54|  return [
    55|    normalizeMessageComparisonValue(message.conversationId),
    56|    normalizeMessageComparisonValue(message.senderRole),
    57|    body,
    58|  ].join('::');
    59|}
    60|
    61|/**
    62| * STABLE ORDERING FIX (owner mandate 2026-07-20 Phase 4D): sort by created_at
    63| * ascending, breaking ties by message id (stable secondary key). Previously
    64| * this sorted ONLY by createdAt — equal-timestamp messages (common when the
    65| * server assigns near-simultaneous timestamps to realtime + optimistic copies)
    66| * changed order after every realtime sync, producing the flicker/reorder the
    67| * owner reported. The id tiebreak is deterministic and stable across reloads.
    68| */
    69|function sortByCreatedAtAscending<T extends MergeableOwnerMessage>(messages: T[]): T[] {
    70|  return [...messages].sort((left, right) => {
    71|    const ta = new Date(left.createdAt).getTime();
    72|    const tb = new Date(right.createdAt).getTime();
    73|    if (ta !== tb) return ta - tb;
    74|    return left.id < right.id ? -1 : left.id > right.id ? 1 : 0;
    75|  });
    76|}
    77|
    78|/**
    79| * Merge remote (authoritative) and local (shadow/fallback) owner messages.
    80| *
    81| * Rules:
    82| * - Remote rows always win.
    83| * - A local row is dropped if its exact signature already exists remotely
    84| *   (true duplicate), OR if a remote row shares its content key — i.e. the same
    85| *   text turn that was successfully re-persisted remotely with a new server
    86| *   timestamp. This prevents the "message shows twice after reload" artifact.
    87| * - Local-only rows (never persisted remotely, e.g. offline/auth-degraded sends)
    88| *   are preserved so the conversation never loses a turn.
    89| */
    90|export function mergeOwnerMessages<T extends MergeableOwnerMessage>(
    91|  remoteMessages: T[],
    92|  localMessages: T[],
    93|): T[] {
    94|  if (localMessages.length === 0) {
    95|    return sortByCreatedAtAscending(remoteMessages);
    96|  }
    97|
    98|  const merged = new Map<string, T>();
    99|  const remoteContentKeys = new Set<string>();
   100|
   101|  for (const message of remoteMessages) {
   102|    merged.set(buildOwnerMessageSignature(message), message);
   103|    const contentKey = buildOwnerMessageContentKey(message);
   104|    if (contentKey) {
   105|      remoteContentKeys.add(contentKey);
   106|    }
   107|  }
   108|
   109|  for (const message of localMessages) {
   110|    const signature = buildOwnerMessageSignature(message);
   111|    if (merged.has(signature)) {
   112|      continue;
   113|    }
   114|    const contentKey = buildOwnerMessageContentKey(message);
   115|    if (contentKey && remoteContentKeys.has(contentKey)) {
   116|      // Stale local copy of a turn that is already persisted remotely.
   117|      continue;
   118|    }
   119|    merged.set(signature, message);
   120|  }
   121|
   122|  return sortByCreatedAtAscending(Array.from(merged.values()));
   123|}
   124|
   125|/**
   126| * Bound the local shadow to the most recent `maxMessages` turns (chronological)
   127| * so the durable cache can never grow without limit. Keeps the newest messages.
   128| */
   129|export function capOwnerMessages<T extends MergeableOwnerMessage>(
   130|  messages: T[],
   131|  maxMessages: number,
   132|): T[] {
   133|  if (maxMessages <= 0 || messages.length <= maxMessages) {
   134|    return sortByCreatedAtAscending(messages);
   135|  }
   136|  return sortByCreatedAtAscending(messages).slice(-maxMessages);
   137|}

