     1|/**
     2| * IVX Chat Pagination (Expo-side)
     3| *
     4| * Owner mandate 2026-07-20 Phase 4 (areas B, C, E): cursor-based pagination
     5| * for older messages, scroll position preservation, and memoized message rows.
     6| *
     7| * This is the Expo-side mirror of backend/services/ivx-chat-pagination.ts. It
     8| * is pure TypeScript (no React, no backend imports) so it is unit-testable and
     9| * tree-shakeable. The chat screen imports these helpers to fetch older messages
    10| * on scroll-to-top via a cursor, prepend them preserving the scroll anchor, and
    11| * keep stable ordering (created_at ascending + id tiebreak) so realtime sync
    12| * never reorders equal-timestamp messages.
    13| */
    14|
    15|export const IVX_CHAT_PAGINATION_MARKER = 'ivx-chat-pagination-2026-07-20';
    16|
    17|/**
    18| * A cursor for pagination. Encodes the created_at + id of the oldest currently-
    19| * loaded message so the next page fetches messages older than that cursor.
    20| */
    21|export type IVXMessageCursor = {
    22|  createdAt: string;
    23|  id: string;
    24|};
    25|
    26|/**
    27| * Encode a cursor to a base64 string for transport. Uses btoa (available in
    28| * React Native + the Metro runtime) with a UTF-8 safe path.
    29| */
    30|export function encodeCursor(cursor: IVXMessageCursor): string {
    31|  const json = JSON.stringify(cursor);
    32|  // btoa is ASCII-only; encode UTF-8 bytes as percent-escaped chars first.
    33|  const utf8 = unescape(encodeURIComponent(json));
    34|  return btoa(utf8);
    35|}
    36|
    37|/**
    38| * Decode a cursor from a base64 string. Returns null on malformed input.
    39| */
    40|export function decodeCursor(encoded: string): IVXMessageCursor | null {
    41|  try {
    42|    const utf8 = atob(encoded);
    43|    const json = decodeURIComponent(escape(utf8));
    44|    const parsed = JSON.parse(json) as IVXMessageCursor;
    45|    if (!parsed.createdAt || !parsed.id) return null;
    46|    return parsed;
    47|  } catch {
    48|    return null;
    49|  }
    50|}
    51|
    52|/**
    53| * The initial page size (newest messages loaded on room open) and the older-
    54| * message page size (loaded when the user scrolls to the top).
    55| */
    56|export const INITIAL_PAGE_SIZE = 120;
    57|export const OLDER_PAGE_SIZE = 80;
    58|
    59|/**
    60| * Stable ordering: sort by created_at ascending, breaking ties by message id
    61| * (stable secondary key). This prevents messages from changing order after
    62| * realtime synchronization when timestamps are equal.
    63| */
    64|export function stableMessageOrder<T extends { id: string; createdAt: string }>(a: T, b: T): number {
    65|  const ta = new Date(a.createdAt).getTime();
    66|  const tb = new Date(b.createdAt).getTime();
    67|  if (ta !== tb) return ta - tb;
    68|  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
    69|}
    70|
    71|/**
    72| * Deduplicate messages by canonical message id. Realtime + optimistic + local
    73| * mirror can produce the same logical message under different ids; the
    74| * canonical id is the remote id if present, else the local id.
    75| */
    76|export function deduplicateMessages<T extends { id: string; remoteId?: string | null }>(messages: T[]): T[] {
    77|  const seen = new Set<string>();
    78|  const result: T[] = [];
    79|  for (const m of messages) {
    80|    const canonical = m.remoteId ?? m.id;
    81|    if (seen.has(canonical)) continue;
    82|    seen.add(canonical);
    83|    result.push(m);
    84|  }
    85|  return result;
    86|}
