    88|/**
    89| * Prepend older messages to the current list, preserving the visible scroll
    90| * position. Returns the merged list (deduped + sorted).
    91| *
    92| * The caller is responsible for preserving the scroll anchor by remembering
    93| * the index of the first visible message BEFORE the prepend and scrolling to
    94| * that message AFTER the prepend.
    95| */
    96|export function prependOlderMessages<T extends { id: string; createdAt: string; remoteId?: string | null }>(
    97|  current: T[],
    98|  older: T[],
    99|): T[] {
   100|  const merged = [...older, ...current];
