   106|/**
   107| * Merge a new realtime message into the current list. If the user is near the
   108| * bottom, the caller should auto-scroll; if the user is reading older
   109| * messages, the caller should show a "new messages" button.
   110| *
   111| * Returns the merged list (deduped + sorted) and whether the message was new.
   112| */
   113|export function mergeRealtimeMessage<T extends { id: string; createdAt: string; remoteId?: string | null }>(
   114|  current: T[],
   115|  incoming: T,
   116|): { messages: T[]; isNew: boolean } {
   117|  const canonical = incoming.remoteId ?? incoming.id;
   118|  const exists = current.some((m) => (m.remoteId ?? m.id) === canonical);
   119|  if (exists) {
   120|    return { messages: current, isNew: false };
   121|  }
   122|  const merged = [...current, incoming];
   123|  merged.sort(stableMessageOrder);
