  1003|function buildSearchSnippet(body: string | null, query: string): string {
  1004|  const normalizedBody = (body ?? '').replace(/\s+/g, ' ').trim();
  1005|  if (!normalizedBody) {
  1006|    return '';
  1007|  }
  1008|
  1009|  const idx = normalizedBody.toLowerCase().indexOf(query.toLowerCase());
  1010|  if (idx < 0) {
  1011|    return normalizedBody.length > 160 ? `${normalizedBody.slice(0, 157)}...` : normalizedBody;
  1012|  }
  1013|
  1014|  const start = Math.max(0, idx - 40);
  1015|  const end = Math.min(normalizedBody.length, idx + query.length + 80);
  1016|  const prefix = start > 0 ? '...' : '';
  1017|  const suffix = end < normalizedBody.length ? '...' : '';
  1018|  return `${prefix}${normalizedBody.slice(start, end)}${suffix}`;
