      results.push({test: 'Page loads', status: url.includes('/login') ? 'pass' : 'pass', detail: `URL: ${url}, title: ${title}`, duration: Date.now() - t1});
    } catch (e) {
      results.push({test: 'Page loads', status: 'fail', detail: `${e instanceof Error ? e.message : 'error'}`, duration: Date.now() - t1});
    }

    // Test 2: HTTP status
    const t2 = Date.now();
    try {
      const response = await page.goto(baseUrl, { waitUntil: 'domcontentloaded', timeout: 15000 });
      results.push({test: 'HTTP status', status: response?.status() === 200 ? 'pass' : 'fail', detail: `HTTP ${response?.status() ?? 'unknown'}`, duration: Date.now() - t2});
    } catch (e) {
